import { Component, h, Prop, Event, EventEmitter, Host, State, Element, Listen } from '@stencil/core';
import classnames from 'classnames';
import { ks } from '@fe-infra/keystone-design-tokens';
import { Slot, Slots, Uncontrollable } from '@src/framework/decorators';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { FormContextValueReconcile } from '@src/components/ks-form/utils';
import { FormBaseComponent } from '@src/components/ks-form/FormBaseComponent';
import { KsIconHelp, KsIconLoading } from '@fe-infra/keystone-icons-stencil';

const prefix = 'switch';

/**
 * @slot default - The label content displayed next to the switch.
 * @slot suffix - The slot for the suffix.
 * @slot description - Slot for the description text of the switch.
 * @slot helpContent - Slot for the help content of the switch.
 * @part base - The base container of the component.
 * @part handle - The circular handle that moves between checked states.
 */
@Component({
  tag: 'ks-switch',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsSwitch extends FormBaseComponent<boolean> {
  static vModel = { prop: 'checked', event: 'ksChange' };
  @Element() el!: HTMLKsSwitchElement;

  /** Indicates whether the switch is disabled. When `true`, the switch cannot be toggled by the user. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;
  /** Indicates whether the switch is currently checked. */
  @Prop() @FormContextValueReconcile({ contextKey: 'valueFromContext' }) checked?: boolean;
  /** The default checked state of the switch when it is first rendered. */
  @Prop() defaultChecked?: boolean;
  @Uncontrollable('checked', 'defaultChecked', 'ksChange') @State() internalCheckedState?: boolean;
  /** Whether the switch should receive focus on render. */
  @Prop() autoFocus?: boolean;
  /** The size of the switch. Can be 'sm' or 'md'. */
  @Prop() size: 'sm' | 'md' = 'md';
  /** Indicates whether the switch is in a loading state. When `true`, a loading indicator will be shown. */
  @Prop() loading?: boolean;
  /** The position of the label relative to the switch. Can be 'start' or 'end'. */
  @Prop() labelPosition: 'start' | 'end' = 'end';
  /** Custom event triggered when the checked state of the switch changes. This event can be used to execute additional actions upon change. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<boolean>;
  /** The slot for the suffix of the switch. */
  @Slot({ slotname: 'suffix' }) private suffixSlots?: Slots;
  /** The component that render the description of the switch. */
  @Slot({ slotname: 'description' }) private descriptionSlots?: Slots;
  /** The slot for the help content inside the tooltip icon */
  @Slot({ slotname: 'helpContent' }) private helpContentSlots?: Slots;

  @Listen('ksChange')
  onKsChange(event: CustomEvent<boolean>) {
    sendActionTracking(this.el, { eventType: 'change', componentParams: { value: event.detail } });

    // FIXME: stencil extend does not support 2 listener on same event
    this.onKsChangeForForm(event);
  }

  constructor() {
    super();
    registerPluginManager(this.el);
  }

  private handleValueChange = () => {
    if (this.disabled || this.loading) {
      return;
    }
    this.internalCheckedState = !this.internalCheckedState;
  };

  private stopPropagation(event: Event) {
    event.stopPropagation();
  }

  render() {
    const classes = classnames(prefix, `${prefix}--${this.size}`, {
      [`${prefix}--disabled`]: this.disabled,
      [`${prefix}--loading`]: this.loading,
      [`${prefix}--checked`]: this.internalCheckedState,
      [`${prefix}--${this.labelPosition}`]: this.labelPosition,
    });
    return (
      <Host class="KsSwitch" role="switch">
        <div class={classes} part="base">
          <button
            id="switch"
            onClick={this.handleValueChange}
            class={`${prefix}__display`}
            role="switch"
            disabled={this.disabled || this.loading}
            autofocus={this.autoFocus}
            aria-checked={String(this.internalCheckedState)}
            data-testid="ks-switch-index-pUsHmY"
          >
            <div class={classnames(`${prefix}__handle`, `${prefix}__handle--${this.size}`)} part="handle">
              {this.loading && <KsIconLoading size="12" color={ks.color.neutral.fillLow} />}
            </div>
          </button>

          <div class={`${prefix}__content`}>
            <div class={`${prefix}__content__header`}>
              <label
                class={`${prefix}__label`}
                htmlFor="switch"
                onClick={this.stopPropagation}
                data-testid="ks-switch-index-3WfYsv"
              >
                <slot />
              </label>
              {this.helpContentSlots && (
                <ks-tooltip class="tooltip">
                  <KsIconHelp size="14" />
                  <slot name="helpContent" slot="content" />
                </ks-tooltip>
              )}
              {this.suffixSlots && <slot name="suffix" />}
            </div>
            {this.descriptionSlots && (
              <div class={`${prefix}__description`}>
                <slot name="description" />
              </div>
            )}
          </div>
        </div>
      </Host>
    );
  }
}
